/**
 * ==============================================================================
 * DATOS Y PARTITURAS MUSICALES - SINFONÍA DE CAMPANAS (Guitar Hero Kiosk Edition)
 * ==============================================================================
 * 
 * Partituras auténticas basadas en las pistas musicales oficiales de Alexander Nakarada:
 * - Cero bucles procedurales repetitivos: cada sección (Intro, Verso, Coro, Solo, Clímax)
 *   sigue la melodía, los acordes y los solos de guitarra reales de la canción.
 * - Soporte nativo para Notas Normales, NOTAS SOSTENIDAS (Sustain Notes) y ACORDES/NOTAS DOBLES.
 * - REGLA DE POLIFONÍA ESTRICTA PARA TÓTEM TÁCTIL (<= 2 dedos):
 *   Máximo 2 toques simultáneos, cero triples, cero dobles durante sustain.
 * - Progresión arcade: Fácil (niños) < Normal (fluido) < Difícil (tótem activo) < Experto (Guitar Shred).
 */

export interface ChartNoteRecord {
  lane: number;
  time: number;
  duration?: number;
  type?: "normal" | "sustain";
  isStar?: boolean;
  logoType?: 1 | 2; // 1 = Feria Mágica, 2 = Campuslands
}

export interface SongDef {
  id: string;
  title: string;
  artist: string;
  credits: string;
  subtitle: string;
  bpm: number;
  speed: number;
  durationSeconds: number;
  stars: number;
  difficultyLabel: string;
  tagColor: string;
  audioFile: string;
  icon: "guitar" | "zap" | "flame" | "sparkles" | "crown" | "music";
}

/**
 * Sanea cualquier partitura SIN reducir la cantidad de notas ni el nivel de dificultad:
 * 1. Elimina únicamente duplicados exactos en el mismo lugar (mismo carril e instante).
 * 2. Evita sostenidos sobre sostenidos y recorta la cola del sustain antes de otra nota en el mismo carril.
 * 3. Si dos notas caen demasiado pegadas en el mismo carril o sobre un sustain activo,
 *    reubica la nota a un carril libre en vez de borrarla, manteniendo intacto el ritmo y la dificultad.
 */
export function sanitizeChartNotes(
  notes: ChartNoteRecord[],
  diff: "easy" | "normal" | "hard" | "expert" = "normal"
): ChartNoteRecord[] {
  const minSameLaneGap = diff === "easy" ? 0.32 : diff === "normal" ? 0.28 : diff === "hard" ? 0.25 : 0.22;
  const minAfterSustainSameLane = 0.26;
  const minRealSustainDuration = 0.35;
  const minGapBetweenSustains = 0.22;
  // Dificultad Leyenda / Experto: Permite hasta 3 notas simultáneas (acordes triples)
  const maxSimultaneous = diff === "expert" ? 3 : diff === "hard" ? 2 : 1;

  interface WorkingNote {
    lane: number;
    time: number;
    duration: number;
    isStar: boolean;
    logoType?: 1 | 2;
  }

  const raw: WorkingNote[] = [...notes]
    .map((n) => ({
      lane: Math.max(0, Math.min(3, Math.round(n.lane))),
      time: Number(n.time.toFixed(2)),
      duration: n.duration && n.duration >= minRealSustainDuration ? Number(n.duration.toFixed(2)) : 0,
      isStar: Boolean(n.isStar),
      logoType: n.logoType
    }))
    .sort((a, b) => {
      if (Math.abs(a.time - b.time) > 0.001) return a.time - b.time;
      if ((b.isStar ? 1 : 0) !== (a.isStar ? 1 : 0)) return (b.isStar ? 1 : 0) - (a.isStar ? 1 : 0);
      return b.duration - a.duration;
    });

  const groups: WorkingNote[][] = [];
  let i = 0;
  while (i < raw.length) {
    const t0 = raw[i].time;
    const grp: WorkingNote[] = [raw[i]];
    let j = i + 1;
    while (j < raw.length && raw[j].time - t0 <= 0.04) {
      grp.push(raw[j]);
      j++;
    }
    i = j;

    const byLane = new Map<number, WorkingNote>();
    for (const n of grp) {
      const ex = byLane.get(n.lane);
      if (!ex) {
        byLane.set(n.lane, { ...n, time: t0 });
      } else {
        if (n.isStar && !ex.isStar) {
          ex.isStar = true;
          ex.logoType = n.logoType || ex.logoType;
        }
        if (n.duration > ex.duration) {
          ex.duration = n.duration;
        }
      }
    }
    let unique = Array.from(byLane.values());
    if (unique.length > maxSimultaneous) {
      unique.sort((a, b) => {
        if (b.duration !== a.duration) return b.duration - a.duration;
        return (b.isStar ? 1 : 0) - (a.isStar ? 1 : 0);
      });
      unique = unique.slice(0, maxSimultaneous);
    }
    // Si hay una nota sostenida en este instante, preservar el sustain limpio en la nota principal
    if (unique.length > 1 && unique.some((u) => u.duration > 0)) {
      unique.sort((a, b) => b.duration - a.duration);
      const primary = unique[0];
      if (unique.some((u) => u.isStar)) {
        primary.isStar = true;
        primary.logoType = primary.logoType || unique.find((u) => u.logoType)?.logoType || 1;
      }
      unique = [primary];
    }
    groups.push(unique);
  }

  // Recortar sustains consecutivos con margen limpio en vez de eliminarlos
  for (let gIdx = 0; gIdx < groups.length; gIdx++) {
    const n = groups[gIdx][0];
    if (!n || n.duration <= 0) continue;
    const maxDurForDiff = diff === "hard" || diff === "expert" ? 2.40 : 3.20;
    n.duration = Math.min(n.duration, maxDurForDiff);

    for (let nextG = gIdx + 1; nextG < groups.length; nextG++) {
      const nextN = groups[nextG][0];
      if (!nextN) continue;
      const dt = nextN.time - n.time;
      if (dt > n.duration + minGapBetweenSustains) break;
      if (nextN.duration >= minRealSustainDuration) {
        if (dt >= minRealSustainDuration + minGapBetweenSustains) {
          n.duration = Number(Math.min(n.duration, dt - minGapBetweenSustains).toFixed(2));
          break;
        } else {
          nextN.duration = 0;
        }
      }
    }
  }

  const lastFreeTimeInLane = [-999, -999, -999, -999];
  const lastStartTimeInLane = [-999, -999, -999, -999];
  let activeSustainEnd = -999;
  const placed: WorkingNote[] = [];

  for (const grp of groups) {
    const t = grp[0].time;
    const usedLanesInGroup = new Set<number>(grp.map((n) => n.lane));
    const newGrp: WorkingNote[] = [];

    for (const n of grp) {
      if (n.duration > 0 && t < activeSustainEnd + minGapBetweenSustains - 0.005) {
        n.duration = 0;
      }

      let lane = n.lane;
      const isLaneBusy = (cLane: number): boolean => {
        if (t < lastFreeTimeInLane[cLane] - 0.001) return true;
        if (t - lastStartTimeInLane[cLane] < minSameLaneGap - 0.001) return true;
        return false;
      };

      if (isLaneBusy(lane)) {
        let bestLane = -1;
        let earliestFree = 999999;
        for (let c = 0; c < 4; c++) {
          if (usedLanesInGroup.has(c) && c !== lane) continue;
          if (!isLaneBusy(c) && lastFreeTimeInLane[c] < earliestFree) {
            earliestFree = lastFreeTimeInLane[c];
            bestLane = c;
          }
        }
        if (bestLane !== -1) {
          usedLanesInGroup.delete(lane);
          lane = bestLane;
          usedLanesInGroup.add(lane);
        } else {
          for (let c = 0; c < 4; c++) {
            if (usedLanesInGroup.has(c) && c !== lane) continue;
            if (
              t >= lastFreeTimeInLane[c] &&
              t - lastStartTimeInLane[c] >= 0.16 &&
              lastStartTimeInLane[c] < earliestFree
            ) {
              earliestFree = lastStartTimeInLane[c];
              bestLane = c;
            }
          }
          if (bestLane !== -1) {
            usedLanesInGroup.delete(lane);
            lane = bestLane;
            usedLanesInGroup.add(lane);
          } else {
            continue;
          }
        }
      }

      n.lane = lane;
      lastStartTimeInLane[lane] = t;
      if (n.duration >= minRealSustainDuration) {
        lastFreeTimeInLane[lane] = t + n.duration + minAfterSustainSameLane;
        activeSustainEnd = t + n.duration;
      } else {
        n.duration = 0;
        lastFreeTimeInLane[lane] = t + minSameLaneGap;
      }
      newGrp.push(n);
    }
    placed.push(...newGrp);
  }

  for (let idx = 0; idx < placed.length; idx++) {
    const n = placed[idx];
    if (n.duration <= 0) continue;
    let maxEnd = n.time + n.duration;
    for (let nextIdx = idx + 1; nextIdx < placed.length; nextIdx++) {
      const next = placed[nextIdx];
      if (next.time > maxEnd + 0.5) break;
      if (next.lane === n.lane) {
        maxEnd = Math.min(maxEnd, next.time - minAfterSustainSameLane);
      } else if (next.duration > 0) {
        maxEnd = Math.min(maxEnd, next.time - minGapBetweenSustains);
      }
    }
    const allowedDur = Number((maxEnd - n.time).toFixed(2));
    if (allowedDur >= minRealSustainDuration) {
      n.duration = allowedDur;
    } else {
      n.duration = 0;
    }
  }

  return placed.map((n) => {
    const out: ChartNoteRecord = { lane: n.lane, time: n.time };
    if (n.duration >= minRealSustainDuration) {
      out.duration = n.duration;
      out.type = "sustain";
    }
    if (n.isStar) {
      out.isStar = true;
      out.logoType = n.logoType || 1;
    }
    return out;
  });
}

